import{_ as a,o as i,c as n,a6 as t}from"./chunks/framework.BBIckNDn.js";const h=JSON.parse('{"title":"第13章 グラフィックスAPI ── OpenGL / DirectX 12 / Vulkan","description":"","frontmatter":{"title":"第13章 グラフィックスAPI ── OpenGL / DirectX 12 / Vulkan","study":{"source":"IT教本","kind":"学習ガイド","status":"学習計画・概要","summary":"エンジンのレンダラはグラフィックスAPIの上に建つ。UE5のRHI、UnityのSRPは D3D12/Vulkan/Metalの抽象化層だ。モダンAPI(D3D12/Vulkan)は"}},"headers":[],"relativePath":"guide/low-level/graphics-apis.md","filePath":"guide/low-level/graphics-apis.md"}'),e={name:"guide/low-level/graphics-apis.md"};function s(r,l,o,d,u,c){return i(),n("div",null,[...l[0]||(l[0]=[t(`<h1 id="第13章-グラフィックスapi-──-opengl-directx-12-vulkan" tabindex="-1">第13章 グラフィックスAPI ── OpenGL / DirectX 12 / Vulkan <a class="header-anchor" href="#第13章-グラフィックスapi-──-opengl-directx-12-vulkan" aria-label="Permalink to &quot;第13章 グラフィックスAPI ── OpenGL / DirectX 12 / Vulkan&quot;">​</a></h1><h2 id="学ぶ理由" tabindex="-1">学ぶ理由 <a class="header-anchor" href="#学ぶ理由" aria-label="Permalink to &quot;学ぶ理由&quot;">​</a></h2><p>エンジンのレンダラはグラフィックスAPIの上に建つ。UE5のRHI、UnityのSRPは D3D12/Vulkan/Metalの抽象化層だ。モダンAPI(D3D12/Vulkan)は 「ドライバがやっていた仕事(メモリ管理・同期・状態管理)をアプリに開放」 したため、<strong>APIを学ぶこと自体がGPUとドライバの仕組みを学ぶこと</strong>になる。 RenderDoc/PIXでフレームを読むにも、API概念(コマンドリスト、バリア、 ディスクリプタ)の語彙が必須である。</p><h2 id="到達目標" tabindex="-1">到達目標 <a class="header-anchor" href="#到達目標" aria-label="Permalink to &quot;到達目標&quot;">​</a></h2><ul><li>旧世代(OpenGL/D3D11)とモダン(D3D12/Vulkan)の設計思想の違いを説明できる</li><li>スワップチェーン・コマンドリスト・フェンスによるCPU-GPU同期を実装できる</li><li>リソースバリア(状態遷移)とディスクリプタの概念を説明できる</li><li>D3D12またはVulkanで「テクスチャ付き立方体」まで自力実装できる</li><li>PSO(パイプラインステートオブジェクト)とシェーダコンパイルの関係を説明できる</li><li>「ドローコールが重い」の正確な意味を説明できる</li></ul><h2 id="前提知識" tabindex="-1">前提知識 <a class="header-anchor" href="#前提知識" aria-label="Permalink to &quot;前提知識&quot;">​</a></h2><p>第8章(OS・ドライバ)、第11章(GPU)、第12章(パイプライン)。C++(第9章)。</p><h2 id="学ぶ内容" tabindex="-1">学ぶ内容 <a class="header-anchor" href="#学ぶ内容" aria-label="Permalink to &quot;学ぶ内容&quot;">​</a></h2><ol><li><strong>APIの系譜と設計思想</strong><ul><li>OpenGL/D3D11(ドライバが賢い、ステートマシン、シングルスレッド前提)</li><li>D3D12/Vulkan/Metal(アプリが賢い、明示的、マルチスレッド前提)</li><li>なぜ移行したか: ドローコールのCPUコスト・ドライバの推測の限界・ マルチコア活用(AZDO→Mantle→の歴史)</li><li>どれを学ぶか: <strong>概念習得はOpenGLかD3D11で速く、本命はD3D12 (Windows/Xbox)を1つ深く。Vulkanは差分で理解</strong>(概念は9割共通)</li></ul></li><li><strong>初期化とスワップチェーン</strong><ul><li>デバイス/アダプタ列挙、デバッグレイヤー(必ず有効化する習慣)</li><li>スワップチェーン: バックバッファ、ダブル/トリプルバッファリング</li><li>Present、VSync、可変リフレッシュ(入力遅延との関係 ← 第14章へ)</li></ul></li><li><strong>コマンド実行モデル(モダンAPIの心臓)</strong><ul><li>コマンドアロケータ→コマンドリストに記録→キューへ提出</li><li>GPUは後から非同期に消費(第11章の回収)</li><li><strong>フェンス</strong>によるCPU-GPU同期、フレームインフライト(2〜3フレーム並走) → 「入力から表示まで数フレームかかる」理由の核心</li><li>複数キュー(グラフィックス/コンピュート/コピー)と非同期コンピュート</li></ul></li><li><strong>リソースとメモリ</strong><ul><li>バッファ/テクスチャ、ヒープ(DEFAULT=VRAM, UPLOAD=CPU可視)</li><li>アップロードの作法(ステージングバッファ→コピー)</li><li><strong>リソースバリア/レイアウト遷移</strong>: 「テクスチャとして読む前に レンダーターゲット書き込み完了を保証」── GPUキャッシュと 圧縮形式の切替をアプリが指示する(第11章の帯域最適化の裏側)</li><li>ディスクリプタ(リソースのGPU向けポインタ)、ディスクリプタヒープ、 ベースのバインドレス化の潮流</li></ul></li><li><strong>パイプラインステートオブジェクト(PSO)</strong><ul><li>シェーダ+ブレンド+深度+ラスタ設定を1オブジェクトに焼き固める</li><li><strong>シェーダコンパイルスタッター</strong>(実行中PSO生成のヒッチ)と PSOキャッシュ ── 現代PCゲームの有名問題の正体</li><li>ルートシグネチャ(D3D12)/パイプラインレイアウト(Vulkan)</li></ul></li><li><strong>描画の1フレーム(統合)</strong><ul><li>リソース更新(定数バッファ)→バリア→パス毎にRT設定→ PSO設定→ディスクリプタ→DrawIndexedInstanced→…→Present→フェンス</li><li><strong>ドローコールのコスト分解</strong>: API呼び出し+ドライバの検証+ ステート切替。インスタンシング・バッチングが効く理由</li></ul></li><li><strong>デバッグとツール(第18章へ接続)</strong><ul><li>デバッグレイヤーのメッセージを読む、GPUバリデーション</li><li>RenderDoc(API横断)と PIX(D3D12特化)の使い分け</li></ul></li></ol><h2 id="重要概念" tabindex="-1">重要概念 <a class="header-anchor" href="#重要概念" aria-label="Permalink to &quot;重要概念&quot;">​</a></h2><ul><li><strong>明示性</strong>: モダンAPIは「ドライバの魔法」を全部アプリに渡した</li><li><strong>コマンドバッファ+フェンス</strong> ── CPUとGPUの生産者消費者関係</li><li><strong>フレームインフライト</strong> ── スループットと遅延のトレードオフ</li><li><strong>バリア</strong> ── GPU内部の並列性とキャッシュを制御する行為</li><li><strong>PSO</strong> ── 実行中のシェーダコンパイルを排除する設計</li></ul><h2 id="ゲーム開発との関係" tabindex="-1">ゲーム開発との関係 <a class="header-anchor" href="#ゲーム開発との関係" aria-label="Permalink to &quot;ゲーム開発との関係&quot;">​</a></h2><table tabindex="0"><thead><tr><th>現場の事象</th><th>この章の知識</th></tr></thead><tbody><tr><td>UEのRHI / UnityのSRP・Graphics API設定</td><td>この章の抽象化層</td></tr><tr><td>シェーダコンパイルスタッター問題</td><td>PSO・ドライバコンパイル</td></tr><tr><td>「ドローコール削減」「バッチング」</td><td>コマンドのCPUコスト</td></tr><tr><td>GPUクラッシュ(デバイスロスト)解析</td><td>バリア・同期ミス・TDR</td></tr><tr><td>入力遅延とトリプルバッファリング</td><td>スワップチェーン・インフライト</td></tr><tr><td>ロード画面でのテクスチャ転送設計</td><td>アップロードヒープ・コピーキュー</td></tr></tbody></table><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><ol><li><strong>Win32ウィンドウ+D3D12初期化</strong>を(チュートリアルを見ながらでよいので) 自分の手で全行書き、画面クリアまで到達せよ。デバッグレイヤー必須。 (Vulkan派は vulkan-tutorial.com で同等の三角形まで)</li><li>三角形→テクスチャ付き立方体→定数バッファでMVP更新、まで拡張せよ (第12章の演習をモダンAPIで再構築する)。</li><li>フェンスを意図的に省略/誤らせて、何が壊れるか観察せよ (デバッグレイヤーの警告を読む訓練)。</li><li>同じモデル1000体を (a)個別ドローコール (b)インスタンシング で描き、 CPU時間を比較せよ(PIXで計測)。</li><li>RenderDocで市販ゲーム級の複雑なフレーム(自作でなくてよい、 例: 任意のOSSゲームやUE5サンプル)をキャプチャし、パス構成 (シャドウ→Gバッファ→ライティング→ポスト→UI)を読解してノートに図解せよ。</li><li>トリプルバッファリングとVSyncオフで入力遅延の体感差を確認せよ。</li></ol><h2 id="おすすめ書籍" tabindex="-1">おすすめ書籍 <a class="header-anchor" href="#おすすめ書籍" aria-label="Permalink to &quot;おすすめ書籍&quot;">​</a></h2><ul><li>『DirectX 12の魔導書』── 和書のD3D12入門定番</li><li>&quot;Introduction to 3D Game Programming with DirectX 12&quot;(Frank Luna) ── 網羅的教科書</li><li>vulkan-tutorial.com / vkguide.dev ── Vulkan無料教材の双璧</li><li>Microsoft公式 DirectX-Specs(仕様書。バリア・PSOの一次情報)</li><li>3dgep.com &quot;Learning DirectX 12&quot; シリーズ(無料・丁寧)</li></ul><h2 id="おすすめoss" tabindex="-1">おすすめOSS <a class="header-anchor" href="#おすすめoss" aria-label="Permalink to &quot;おすすめOSS&quot;">​</a></h2><ul><li><strong>DirectX-Graphics-Samples</strong>(Microsoft公式サンプル)</li><li><strong>The-Forge</strong>(製品級クロスAPIレンダラ)── 本物の設計を読む</li><li><strong>bgfx / Diligent Engine</strong> ── API抽象化層の設計見本(UEのRHIの雛形理解)</li><li>D3D12MemoryAllocator / VulkanMemoryAllocator(AMD)── GPUメモリ管理の実務</li></ul><h2 id="おすすめ動画" tabindex="-1">おすすめ動画 <a class="header-anchor" href="#おすすめ動画" aria-label="Permalink to &quot;おすすめ動画&quot;">​</a></h2><ul><li>GDC &quot;Getting Started with DirectX 12 / Vulkan&quot; 系講演</li><li>3dgep・The ChernoのD3D12/Vulkan回</li><li>GDC &quot;Vulkan Fast Paths&quot;(AMD)、&quot;Practical DirectX 12&quot;(NVIDIA)</li></ul><h2 id="読むべきソースコード" tabindex="-1">読むべきソースコード <a class="header-anchor" href="#読むべきソースコード" aria-label="Permalink to &quot;読むべきソースコード&quot;">​</a></h2><ul><li>DirectX-Graphics-Samples の HelloTriangle → HelloTexture → HelloFrameBuffering (この3つを読み切れば骨格は完成)</li><li>UE5 <code>Engine/Source/Runtime/D3D12RHI/</code>(第17章で本格読解する場所の下見)</li><li>The-Forge のフレーム構築部</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>D3D11とD3D12の最大の違いを「誰が何を管理するか」で説明せよ。</li><li>コマンドリスト・キュー・フェンスの関係を生産者消費者で説明せよ。</li><li>フレームインフライトが2〜3ある理由と、入力遅延への影響は?</li><li>リソースバリアは何を保証するものか。なぜ手動なのか。</li><li>PSOはなぜ「事前に」作るのか。実行中に作ると何が起きるか。</li><li>ドローコールのコストはCPU側とGPU側のどちらに主にかかるか。その内訳は?</li><li>スワップチェーンのPresentから画面点灯までに何が起きるか(概要)。</li></ol><hr><h2 id="この章がゲームのどこで使われているか" tabindex="-1">この章がゲームのどこで使われているか <a class="header-anchor" href="#この章がゲームのどこで使われているか" aria-label="Permalink to &quot;この章がゲームのどこで使われているか&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>エンジンのレンダラ(第15,17章)          この章のAPI            GPU(第11章)</span></span>
<span class="line"><span>──────────────────────────────────────────────────────────</span></span>
<span class="line"><span>シーン走査・カリング</span></span>
<span class="line"><span> → 描画パス構築(レンダーグラフ)</span></span>
<span class="line"><span> → ソート済み描画リスト</span></span>
<span class="line"><span>   → RHI/SRP抽象層 ─────→ コマンドリスト記録</span></span>
<span class="line"><span>                           バリア/PSO/ディスクリプタ</span></span>
<span class="line"><span>                           ExecuteCommandLists ──DMA→ リングバッファ</span></span>
<span class="line"><span>                           Present                    → 実行(第12章の</span></span>
<span class="line"><span>                           フェンス待ち ←──完了通知──     パイプライン)</span></span>
<span class="line"><span>──────────────────────────────────────────────────────────</span></span>
<span class="line"><span>UE5: FRHICommandList → D3D12RHI    Unity: SRP → GfxDevice</span></span>
<span class="line"><span>= どのエンジンでも「この章」がエンジンとGPUの結節点</span></span></code></pre></div>`,28)])])}const P=a(e,[["render",s]]);export{h as __pageData,P as default};
